    background = min(set(v for row in grid for v in row),
                     key=lambda v: sum(row.count(v) for row in grid))
    reachable = set()
    stack = []
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background:
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background:
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        if (r, c) in reachable or grid[r][c] != background:
            continue
        reachable.add((r, c))
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in reachable:
                stack.append((nr, nc))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and (r, c) not in reachable:
                out[r][c] = 4
